class Solution {
    public void reverseString(char[] s) {
        int n = s.length;
        char[] tmp = new char[n];
        for (int i = 0; i < n; i++) {
            tmp[i] = s[n - 1 - i];
        }
        // 题目要求原地修改，必须拷回入参
        for (int i = 0; i < n; i++) {
            s[i] = tmp[i];
        }
    }
}

class Solution {
    public void reverseString(char[] s) {
        int left = 0, right = s.length - 1;
        while (left < right) {
            char tmp = s[left];
            s[left] = s[right];
            s[right] = tmp;
            left++;
            right--;
        }
    }
}

class Solution {
    public void reverseString(char[] s) {
        // 把两个指针的移动写进 for 头，从结构上避免「忘了写 i++ 导致死循环」
        for (int i = 0, j = s.length - 1; i < j; i++, j--) {
            char tmp = s[i];
            s[i] = s[j];
            s[j] = tmp;
        }
    }
}
